-- Frozen pristine SQLite catalog fixture; do not derive from the latest schema.
PRAGMA foreign_keys = OFF;
BEGIN TRANSACTION;
CREATE TABLE job_attempts (
    attempt_id TEXT PRIMARY KEY,
    job_id TEXT NOT NULL REFERENCES jobs(job_id),
    attempt_number INTEGER NOT NULL CHECK (attempt_number > 0),
    supervisor_instance_id TEXT NOT NULL,
    state TEXT NOT NULL CHECK (
        state IN ('STARTING', 'RUNNING', 'SUCCEEDED',
                  'FAILED', 'CANCELLED', 'INTERRUPTED')
    ),
    state_version INTEGER NOT NULL CHECK (state_version > 0),
    result_artifact_id TEXT,
    created_at_ns INTEGER NOT NULL,
    updated_at_ns INTEGER NOT NULL,
    UNIQUE (job_id, attempt_number)
);
INSERT INTO "job_attempts" VALUES('attempt-v1-running','job-v1-running',1,'supervisor-v1','RUNNING',2,NULL,300,400);
INSERT INTO "job_attempts" VALUES('attempt-v1-succeeded','job-v1-succeeded',1,'supervisor-v1','SUCCEEDED',3,'6666666666666666666666666666666666666666666666666666666666666666',301,401);
INSERT INTO "job_attempts" VALUES('attempt-v1-retry','job-v1-retry',1,'supervisor-v1','FAILED',3,NULL,302,402);
CREATE TABLE jobs (
    job_id TEXT PRIMARY KEY,
    command_type TEXT NOT NULL,
    idempotency_key TEXT NOT NULL,
    request_digest TEXT NOT NULL,
    resolved_spec BLOB NOT NULL,
    state TEXT NOT NULL CHECK (
        state IN ('QUEUED', 'STARTING', 'RUNNING', 'SUCCEEDED',
                  'FAILED', 'CANCELLED', 'INTERRUPTED')
    ),
    state_version INTEGER NOT NULL CHECK (state_version >= 0),
    cancel_requested INTEGER NOT NULL DEFAULT 0 CHECK (cancel_requested IN (0, 1)),
    current_attempt_id TEXT,
    submitted_at_ns INTEGER NOT NULL,
    updated_at_ns INTEGER NOT NULL,
    UNIQUE (command_type, idempotency_key),
    FOREIGN KEY (current_attempt_id) REFERENCES job_attempts(attempt_id)
        DEFERRABLE INITIALLY DEFERRED
);
INSERT INTO "jobs" VALUES('job-v1-queued','COMPILE_REPLAY','key-v1-queued','3d89cfd3c8eb0ea0243da752b82d43ed8dba5bdc2ed849ea49e7b54557a9af56',X'','QUEUED',0,0,NULL,100,200);
INSERT INTO "jobs" VALUES('job-v1-running','RUN_BACKTEST','key-v1-running','4aa924bb30f03dc440f5c6a116708b5260240c0189fd5b135b73e89fe882f554',X'','RUNNING',2,0,'attempt-v1-running',101,201);
INSERT INTO "jobs" VALUES('job-v1-succeeded','RUN_BACKTEST','key-v1-succeeded','cacc3b4aa7aed92c7ed61c58c47529607d1a1580affec0ab68ada7d2ea995410',X'','SUCCEEDED',3,0,'attempt-v1-succeeded',102,202);
INSERT INTO "jobs" VALUES('job-v1-retry','RUN_SWEEP','key-v1-retry','0a700f42bd5f34b4fa85ef2f5a19db34c21b94a0cfc579ea8807ae8922af376a',X'','QUEUED',3,0,NULL,103,203);
CREATE INDEX jobs_claim_order_idx
    ON jobs(state, cancel_requested, submitted_at_ns, job_id);
CREATE INDEX job_attempts_job_idx
    ON job_attempts(job_id, attempt_number);
CREATE TRIGGER jobs_immutable_command
BEFORE UPDATE OF command_type, idempotency_key, request_digest, resolved_spec ON jobs
BEGIN
    SELECT RAISE(ABORT, 'resolved job command is immutable');
END;
COMMIT;
PRAGMA foreign_keys = ON;
PRAGMA user_version = 1;
